$ErrorActionPreference = "Stop"

$path = "app\admin\page.tsx"
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)
$content = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)

$anchor1 = "    ]);`n`n  return ("
$queryB64 = ""
$queryBlock = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($queryB64))

if ($content -notlike "*$anchor1*") {
    Write-Host "WARNING: anchor1 not found (Promise.all closing). No changes made." -ForegroundColor Yellow
    exit 1
}
$replacement1 = "    ]);`n`n" + $queryBlock + "`n  return ("
$content = $content.Replace($anchor1, $replacement1)
Write-Host "Step 1/2: query block inserted." -ForegroundColor Green

$cardB64 = ""
$cardBlock = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($cardB64))
$anchor2 = "        {/* Recent sessions overview table */}"
if ($content -notlike "*$anchor2*") {
    Write-Host "WARNING: anchor2 not found (Recent sessions comment). No changes made to card section." -ForegroundColor Yellow
    exit 1
}
$content = $content.Replace($anchor2, $cardBlock + $anchor2)
Write-Host "Step 2/2: stats cards inserted." -ForegroundColor Green

[System.IO.File]::WriteAllText($path, $content, $utf8NoBom)
Write-Host "File updated successfully: app/admin/page.tsx" -ForegroundColor Green
Write-Host "Added: most-frequent members card + longest-absence members card." -ForegroundColor Cyan